                                                                                                                                    "apiVersion": "1.0.0",
                                                                                                                                    "controllerElementId": null,
                                                                                                                                    "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.event\n */\nfunction evaluateEvent({\n    api,\n    event\n}) {\n    var selectedRelatedList = {};\n    var currentCard = api.state.selectedRelatedList.selectedCard;\n    var isVisible = api.state.selectedRelatedList.isVisible;\n\n    if ((currentCard == 3) && isVisible)\n        isVisible = false;\n    else\n        isVisible = true;\n\n    return {\n        propName: \"selectedRelatedList\",\n        value: {\n\t\t\t\"isVisible\": isVisible,\n\t\t\t\"selectedCard\": 3\n\t\t}\n    };\n}",
                                                                                                                                    "scriptSysId": null,
                                                                                                                                    "target": null
                                                                                                                                },
